const previousDigest = $('Load checkpoint').first().json.previousDigest ?? null;
const snapshot = $('GET live Shopify SKU catalog').first().json;
if (!snapshot || snapshot.source !== 'shopify' || snapshot.complete !== true || !Array.isArray(snapshot.items)) {
  throw new Error('Shopify catalog endpoint did not return a complete snapshot');
}
if (snapshot.itemCount !== snapshot.items.length) {
  throw new Error('Shopify catalog itemCount does not match items');
}
if (snapshot.items.length > 5000) {
  throw new Error('Shopify catalog exceeds max audit batch 5000');
}
const items = snapshot.items.map((row) => ({
  externalVariantId: String(row.externalVariantId || ''),
  sku: row.sku == null ? '' : String(row.sku),
}));
if (items.some((row) => !row.externalVariantId)) {
  throw new Error('Shopify catalog contains a variant without an ID');
}
const workspaceKey = $env.SKU_API_WORKSPACE || 'synarava-shop';
const correlationId = `n8n-catalog-audit-${Date.now()}`;
return [{ json: { workspaceKey, previousDigest, correlationId, body: { items, previousDigest, correlationId } } }];

